using UnityEngine;
using UnityEngine.Tilemaps;

namespace TWF
{
    // The original 64x64 world art (generated by TWF/Generate 64px Art).
    public class ArtSet : ScriptableObject
    {
        static ArtSet instance;

        public static ArtSet Instance
        {
            get
            {
                if (instance == null) instance = Resources.Load<ArtSet>("TWF/ArtSet");
                return instance;
            }
        }

        public TileBase[] forestGround, marshGround, ruinsGround, emberGround;
        public TileBase[] forestPath, marshPath, ruinsPath, emberPath;
        [Tooltip("Index = mask of grass neighbours: 1 N, 2 E, 4 S, 8 W.")]
        public TileBase[] forestFringe, marshFringe;
        [Tooltip("Forest, Marsh, Ruins, Ember.")]
        public Texture2D[] cliff;
        public Texture2D brick;

        public Sprite[] oak, birch, pine, willow, deadTree, charredTree, mushroomRed, mushroomPurple;
        public Sprite[] rockSmall, rockLarge, rockMossy, bush, fern, pillar, brokenPillar;

        public TileBase[] Ground(Biome b) =>
            b == Biome.Marsh ? marshGround : b == Biome.Ruins ? ruinsGround : b == Biome.Ember ? emberGround : forestGround;

        public TileBase[] Path(Biome b) =>
            b == Biome.Marsh ? marshPath : b == Biome.Ruins ? ruinsPath : b == Biome.Ember ? emberPath : forestPath;

        public TileBase[] Fringe(Biome b) =>
            b == Biome.Marsh ? marshFringe : b == Biome.Forest ? forestFringe : null;

        public Texture2D Cliff(Biome b) =>
            cliff == null || cliff.Length < 4 ? null : b == Biome.Marsh ? cliff[1] : b == Biome.Ruins ? cliff[2] : b == Biome.Ember ? cliff[3] : cliff[0];
    }
}
